// OBX - Observation segment
// The OBX segment is used to transmit a single observation or observation fragment.  It represents the smallest indivisible unit of a report.
//
// Its principal mission is to carry information about observations in report messages.  But the OBX can also be part of an observation order (see Section 4.2, “Order Message Definitions”).  In this case, the OBX carries clinical information needed by the filler to interpret the observation the filler makes.  For example, an OBX is needed to report the inspired oxygen on an order for a blood oxygen to a blood gas lab, or to report the menstrual phase information which should be included on an order for a pap smear to a cytology lab.  Appendix 7A includes codes for identifying many of pieces of information needed by observation producing services to properly interpret a test result.  OBX is also found in other HL7 messages that need to include patient clinical information.
type OBX struct {
	SetIDOBX                 *SI      `hl7:"1"`
	ValueType                *ID      `hl7:"2"`
	ObservationIdentifier    *CE      `hl7:"3,required"`
	ObservationSubID         *ST      `hl7:"4"`
	ObservationValue         []VARIES `hl7:"5"`
	Units                    *CE      `hl7:"6"`
	ReferencesRange          *ST      `hl7:"7"`
	AbnormalFlags            []ID     `hl7:"8"`
	Probability              *NM      `hl7:"9"`
	NatureOfAbnormalTest     []ID     `hl7:"10"`
	ObservResultStatus       *ID      `hl7:"11,required"`
	DateLastObsNormalValues  *TS      `hl7:"12"`
	UserDefinedAccessChecks  *ST      `hl7:"13"`
	DateTimeOfTheObservation *TS      `hl7:"14"`
	ProducerSID              *CE      `hl7:"15"`
	ResponsibleObserver      *XCN     `hl7:"16"`
	ObservationMethod        []CE     `hl7:"17"`
}

func NewOBX() *OBX {
	return &OBX{}
}

func (s *OBX) Validate() error {

	if s.ObservationIdentifier == nil {
		return fmt.Errorf("OBX.ObservationIdentifier is required")
	}
	if s.ObservationIdentifier != nil {
		if err := s.ObservationIdentifier.Validate(); err != nil {
			return fmt.Errorf("OBX.ObservationIdentifier: %w", err)
		}
	}

	for _, item := range s.ObservationValue {
		if string(item) == "" {
			return fmt.Errorf("OBX.ObservationValue item is empty")
		}
	}

	if s.Units != nil {
		if err := s.Units.Validate(); err != nil {
			return fmt.Errorf("OBX.Units: %w", err)
		}
	}

	for _, item := range s.AbnormalFlags {
		if string(item) == "" {
			return fmt.Errorf("OBX.AbnormalFlags item is empty")
		}
	}

	for _, item := range s.NatureOfAbnormalTest {
		if string(item) == "" {
			return fmt.Errorf("OBX.NatureOfAbnormalTest item is empty")
		}
	}

	if s.ObservResultStatus == nil {
		return fmt.Errorf("OBX.ObservResultStatus is required")
	}
	if string(*s.ObservResultStatus) == "" {
		return fmt.Errorf("OBX.ObservResultStatus is empty")
	}

	if s.DateLastObsNormalValues != nil {
		if err := s.DateLastObsNormalValues.Validate(); err != nil {
			return fmt.Errorf("OBX.DateLastObsNormalValues: %w", err)
		}
	}

	if s.DateTimeOfTheObservation != nil {
		if err := s.DateTimeOfTheObservation.Validate(); err != nil {
			return fmt.Errorf("OBX.DateTimeOfTheObservation: %w", err)
		}
	}

	if s.ProducerSID != nil {
		if err := s.ProducerSID.Validate(); err != nil {
			return fmt.Errorf("OBX.ProducerSID: %w", err)
		}
	}

	if s.ResponsibleObserver != nil {
		if err := s.ResponsibleObserver.Validate(); err != nil {
			return fmt.Errorf("OBX.ResponsibleObserver: %w", err)
		}
	}

	for _, item := range s.ObservationMethod {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OBX.ObservationMethod: %w", err)
		}
	}
	return nil
}

