// PRD - Provider Data
// This segment will be employed as part of a patient referral message and its related transactions.  The PRD segment contains data specifically focused on a referral, and it is inter-enterprise in nature.  The justification for this new segment comes from the fact that we are dealing with referrals that are external to the facilities that received them.  Therefore, using a segment such as the current PV1 would be inadequate for all the return information that may be required by the receiving facility or application.  In addition, the PV1 does not always provide information sufficient to enable the external facility to make a complete identification of the referring entity.  The information contained in the PRD segment will include the referring provider, the referred-to provider, the referred-to location or service, and the referring provider clinic address.
type PRD struct {
	Role                             []CE    `hl7:"1,required"`
	ProviderName                     []XPN   `hl7:"2"`
	ProviderAddress                  *XAD    `hl7:"3"`
	ProviderLocation                 *PL     `hl7:"4"`
	ProviderCommunicationInformation []XTN   `hl7:"5"`
	PreferredMethodOfContact         *CE     `hl7:"6"`
	ProviderIdentifiers              []CM_PI `hl7:"7"`
	EffectiveStartDateOfRole         *TS     `hl7:"8"`
	EffectiveEndDateOfRole           *TS     `hl7:"9"`
}

func NewPRD() *PRD {
	return &PRD{}
}

func (s *PRD) Validate() error {

	if len(s.Role) == 0 {
		return fmt.Errorf("PRD.Role is required")
	}
	for _, item := range s.Role {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PRD.Role: %w", err)
		}
	}

	for _, item := range s.ProviderName {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PRD.ProviderName: %w", err)
		}
	}

	if s.ProviderAddress != nil {
		if err := s.ProviderAddress.Validate(); err != nil {
			return fmt.Errorf("PRD.ProviderAddress: %w", err)
		}
	}

	if s.ProviderLocation != nil {
		if err := s.ProviderLocation.Validate(); err != nil {
			return fmt.Errorf("PRD.ProviderLocation: %w", err)
		}
	}

	for _, item := range s.ProviderCommunicationInformation {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PRD.ProviderCommunicationInformation: %w", err)
		}
	}

	if s.PreferredMethodOfContact != nil {
		if err := s.PreferredMethodOfContact.Validate(); err != nil {
			return fmt.Errorf("PRD.PreferredMethodOfContact: %w", err)
		}
	}

	for _, item := range s.ProviderIdentifiers {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PRD.ProviderIdentifiers: %w", err)
		}
	}

	if s.EffectiveStartDateOfRole != nil {
		if err := s.EffectiveStartDateOfRole.Validate(); err != nil {
			return fmt.Errorf("PRD.EffectiveStartDateOfRole: %w", err)
		}
	}

	if s.EffectiveEndDateOfRole != nil {
		if err := s.EffectiveEndDateOfRole.Validate(); err != nil {
			return fmt.Errorf("PRD.EffectiveEndDateOfRole: %w", err)
		}
	}
	return nil
}

func (s *PRD) AddRole(v CE) *PRD {
	s.Role = append(s.Role, v)
	return s
}

func (s *PRD) AddProviderName(v XPN) *PRD {
	s.ProviderName = append(s.ProviderName, v)
	return s
}

