// RDF - Table Row Definition
// The RDF segment defines the content of the row data segments (RDT) in the Tabular Data Response Message (TBR).  It is used in two ways:
//
// - As an optional segment in the SPQ message (Stored Procedure Request) or the VQQ (Virtual Table Query) message, this segment can be used to limit the number of columns returned and to specify what column positions the fields occupy (where supported, these features can be used to override the defaults for the particular query).  If omitted, all fields defined for the query are returned in their default column order.
// - As a required segment on the tabular data response message (TBR), this segment defines the contents of the table row data (RDT) segments that follow.
type RDF struct {
	NumberOfColumnsPerRow *NM   `hl7:"1,required"`
	ColumnDescription     []RCD `hl7:"2,required"`
}

func NewRDF() *RDF {
	return &RDF{}
}

func (s *RDF) Validate() error {

	if s.NumberOfColumnsPerRow == nil {
		return fmt.Errorf("RDF.NumberOfColumnsPerRow is required")
	}
	if string(*s.NumberOfColumnsPerRow) == "" {
		return fmt.Errorf("RDF.NumberOfColumnsPerRow is empty")
	}

	if len(s.ColumnDescription) == 0 {
		return fmt.Errorf("RDF.ColumnDescription is required")
	}
	for _, item := range s.ColumnDescription {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("RDF.ColumnDescription: %w", err)
		}
	}
	return nil
}

func (s *RDF) SetNumberOfColumnsPerRow(v *NM) *RDF {
	s.NumberOfColumnsPerRow = v
	return s
}

func (s *RDF) AddColumnDescription(v RCD) *RDF {
	s.ColumnDescription = append(s.ColumnDescription, v)
	return s
}

